7	)
8	
9	const pathBandwidthRealtime = "/api/bandwidth-stats/nodes/realtime"
10	
11	// NodeRate is what a node is carrying right now, as the panel reports it.
12	type NodeRate struct {
13		NodeUUID string
14		Name     string
15		// DownBps and UpBps are the panel's "downloadSpeedBps" and "uploadSpeedBps", taken as bytes per second.
16		DownBps int64
17		UpBps   int64
18	}
19	
20	// RealtimeReader is implemented by adapters whose panel can say what its nodes carry right now. It is a
21	// separate interface because older panels lack the endpoint.
22	type RealtimeReader interface {
23		NodesRealtime(ctx context.Context) ([]NodeRate, error)
24	}
25	
26	func (a *V3) NodesRealtime(ctx context.Context) ([]NodeRate, error) {
27		body, err := a.get(ctx, pathBandwidthRealtime, nil)
28		if err != nil {
29			return nil, err
30		}
31		var env struct {
32			Response []map[string]json.RawMessage `json:"response"`
33		}
34		if err := decode(body, &env); err != nil {
35			return nil, err
36		}
37		out := make([]NodeRate, 0, len(env.Response))
38		for _, row := range env.Response {
39			id := rawString(row, "nodeUuid")
40			if id == "" {
41				continue // an identity we cannot trust is not shown
42			}
43			r := NodeRate{NodeUUID: id, Name: rawString(row, "nodeName")}
44			if v := byteCount(row["downloadSpeedBps"]); v != nil {
45				r.DownBps = *v
46			}
47			if v := byteCount(row["uploadSpeedBps"]); v != nil {
48				r.UpBps = *v
49			}
50			out = append(out, r)
51		}
52		if len(env.Response) > 0 && len(out) == 0 {
53			return nil, &APIError{Code: CodeIncompatible}
54		}
55		sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
56		return out, nil
57	}
