40	func (a *V3) get(ctx context.Context, path string, q url.Values) ([]byte, error) {
41		u := a.base + path
42		if len(q) > 0 {
43			u += "?" + q.Encode()
44		}
45		resp, err := a.g.Get(ctx, u, http.Header{"Authorization": [REDACTED]"Bearer " + a.token}})
46		if err != nil {
47			return nil, err
48		}
49		switch {
50		case resp.Status >= 200 && resp.Status < 300:
51			return resp.Body, nil
52		case resp.Status == 401:
53			return nil, &APIError{Code: CodeUnauthorized, Status: 401}
54		case resp.Status == 403:
55			return nil, &APIError{Code: CodeForbidden, Status: 403}
56		case resp.Status == 404:
57			return nil, &APIError{Code: CodeNotFound, Status: 404}
58		case resp.Status == 429:
59			return nil, &APIError{Code: CodeRateLimited, Status: 429, RetryAfter: 30 * time.Second}
60		case resp.Status >= 500:
61			return nil, &APIError{Code: CodeUpstream, Status: resp.Status}
62		default:
63			return nil, &APIError{Code: CodeUnexpected, Status: resp.Status}
64		}
65	}
66	
