		s.writeErr(w, r, http.StatusInternalServerError, "internal", "internal error")
		return
	}
	asked, err := s.Store.SubscriptionsAsked(r.Context(), scope, from, to)
	if err != nil {
		s.writeErr(w, r, http.StatusInternalServerError, "internal", "internal error")
		return
	}
	panels, err := s.Store.ListPanels(r.Context(), scope)
